#include <array>
#include <deque>
#include <memory>
#include <string>
#include <thread>
#include <utility>
#include <vector>

#include <boost/asio.hpp>

using boost::asio::ip::tcp;

class Session : public std::enable_shared_from_this<Session> {
 public:
  explicit Session(tcp::socket socket) : socket_(std::move(socket)) {}

  void start() { do_read(); }

 private:
  void send(std::string message) {
    outbox_.push_back(std::move(message));
    if (outbox_.size() == 1) do_write();
  }

  void do_read() {
    auto self = shared_from_this();
    socket_.async_read_some(boost::asio::buffer(data_),
        [self](boost::system::error_code ec, std::size_t length) {
          if (ec) return;
          self->send(std::string(self->data_.data(), length));
          self->do_read();
        });
  }

  void do_write() {
    auto self = shared_from_this();
    boost::asio::async_write(socket_, boost::asio::buffer(outbox_.front()),
        [self](boost::system::error_code ec, std::size_t) {
          if (ec) return;
          self->outbox_.pop_front();
          if (!self->outbox_.empty()) self->do_write();
        });
  }

  tcp::socket socket_;
  std::array<char, 1024> data_;
  std::deque<std::string> outbox_;
};

void accept_loop(tcp::acceptor& acceptor) {
  acceptor.async_accept([&acceptor](boost::system::error_code ec, tcp::socket socket) {
    if (!ec) std::make_shared<Session>(std::move(socket))->start();
    accept_loop(acceptor);
  });
}

int main() {
  boost::asio::io_context io;
  tcp::acceptor acceptor(io, tcp::endpoint(tcp::v4(), 7000));
  accept_loop(acceptor);

  std::vector<std::thread> threads;
  for (int i = 0; i < 4; ++i) threads.emplace_back([&io] { io.run(); });
  for (auto& t : threads) t.join();
}

